    <script>
        // 安全获取对象值的函数
        function SafeGetValue(obj, path, defaultValue = "N/A") {
            let keys = Array.isArray(path) ? path : path.split('.');
            let current = obj;
            for (let i = 0; i < keys.length; i++) {
                if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                    return defaultValue;
                }
                current = current[keys[i]];
            }
            return current === undefined || current === null ? defaultValue : current;
        }

        // 更新文本值的函数
        function updateTextValue(elementId, rawValue) {
            const element = document.getElementById(elementId);
            if (!element) return;
            let displayValue = Array.isArray(rawValue) ? rawValue[0] : rawValue;
            let valueStr = String(displayValue).replace(/\s*\([^)]*\)$/, '').trim();
            const parts = valueStr.split('->');
            element.innerText = parts[parts.length - 1].trim();
        }

        // 更新弹幕的函数
        function updateDanmaku(danmakuArray) {
            const container = document.getElementById('danmaku-container');
            if (!container || !Array.isArray(danmakuArray)) return;
            // 只更新前10条弹幕
            for (let i = 0; i < 10; i++) {
                const element = document.getElementById(`danmaku-${i + 1}`);
                if (element) {
                    element.innerText = SafeGetValue(danmakuArray, `[${i}]`, '');
                }
            }
        }

        // 更新进度条的函数
        function updateProgressBar(elementId, current, max) {
            const element = document.getElementById(elementId);
            if (!element) return;
            const percentage = max > 0 ? Math.round((current / max) * 100) : 0;
            element.style.width = percentage + '%';
            const textElement = document.getElementById('clinic-exp-progress');
            if (textElement) {
                textElement.innerText = `${current}/${max}`;
            }
        }

        // 初始化显示函数
        async function initDisplay() {
            try {
                // 获取游戏数据
                const messages = await getChatMessages(getCurrentMessageId());
                const gameData = messages?.[0]?.data;
                const characterData = gameData?.display_data || gameData?.stat_data;

                if (!characterData) {
                    console.log('无法加载游戏数据');
                    return;
                }

                // 更新直播间
                updateTextValue('live-date', SafeGetValue(characterData, '直播间.日期'));
                updateTextValue('live-time', SafeGetValue(characterData, '直播间.时间'));
                updateTextValue('live-weather', SafeGetValue(characterData, '直播间.天气'));
                updateTextValue('live-location', SafeGetValue(characterData, '直播间.地点'));
                updateTextValue('live-environment', SafeGetValue(characterData, '直播间.周围环境'));

// 更新弹幕
updateTextValue('danmaku-1', SafeGetValue(characterData, '直播间.弹幕1'));
updateTextValue('danmaku-2', SafeGetValue(characterData, '直播间.弹幕2'));
updateTextValue('danmaku-3', SafeGetValue(characterData, '直播间.弹幕3'));
