updateTextValue('danmaku-7', SafeGetValue(characterData, '直播间.弹幕7'));
updateTextValue('danmaku-8', SafeGetValue(characterData, '直播间.弹幕8'));
updateTextValue('danmaku-9', SafeGetValue(characterData, '直播间.弹幕9'));
updateTextValue('danmaku-10', SafeGetValue(characterData, '直播间.弹幕10'));

                // 更新病人信息
                updateTextValue('patient-level', SafeGetValue(characterData, '病人信息.评级'));
                updateTextValue('patient-name', SafeGetValue(characterData, '病人信息.姓名'));
                updateTextValue('patient-age', SafeGetValue(characterData, '病人信息.性格'));
                updateTextValue('patient-body-type', SafeGetValue(characterData, '病人信息.体型'));
                updateTextValue('patient-family', SafeGetValue(characterData, '病人信息.关系情况'));
                updateTextValue('patient-features', SafeGetValue(characterData, '病人信息.身体特征'));
                updateTextValue('patient-upper-wear', SafeGetValue(characterData, '病人信息.上半身服装'));
                updateTextValue('patient-lower-wear', SafeGetValue(characterData, '病人信息.下半身服装'));
                updateTextValue('patient-underwear', SafeGetValue(characterData, '病人信息.内裤胸罩'));
                updateTextValue('patient-footwear', SafeGetValue(characterData, '病人信息.袜子鞋子'));

                // 更新治疗信息
                updateTextValue('treatment-symptoms', SafeGetValue(characterData, '治疗信息.病状简述'));
                updateTextValue('treatment-goal', SafeGetValue(characterData, '治疗信息.治疗述求'));
